  <script>
    // Mobile menu toggle
    const mobileMenuBtn = document.getElementById('mobileMenuBtn');
    const navLinks = document.getElementById('navLinks');
    mobileMenuBtn.addEventListener('click', () => {
      navLinks.classList.toggle('active');
    });

    // Close mobile menu on link click
    navLinks.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        navLinks.classList.remove('active');
      });
    });

    // Product Carousel
    const carouselTrack = document.getElementById('carouselTrack');
    const prevBtn = document.getElementById('carouselPrev');
    const nextBtn = document.getElementById('carouselNext');
    let carouselPos = 0;
    const cardWidth = 284; // 260px card + 24px gap

    function getMaxScroll() {
      return Math.max(0, carouselTrack.scrollWidth - carouselTrack.parentElement.offsetWidth);
    }

    function updateCarousel() {
      carouselTrack.style.transform = `translateX(-${carouselPos}px)`;
    }

    nextBtn.addEventListener('click', () => {
      const maxScroll = getMaxScroll();
      carouselPos = Math.min(carouselPos + cardWidth, maxScroll);
      updateCarousel();
    });

    prevBtn.addEventListener('click', () => {
      carouselPos = Math.max(carouselPos - cardWidth, 0);
      updateCarousel();
    });

    // Store Locator
    const zipInput = document.getElementById('zipInput');
    const storeSearchBtn = document.getElementById('storeSearchBtn');
    const storeResults = document.getElementById('storeResults');

    function searchStores() {
      const zip = zipInput.value.trim();
      if (zip.length >= 3) {
        storeResults.classList.add('active');
        storeResults.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    }

    storeSearchBtn.addEventListener('click', searchStores);
    zipInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') searchStores();
    });

    // Newsletter
    const emailInput = document.getElementById('emailInput');
    const subscribeBtn = document.getElementById('subscribeBtn');
    const newsletterConfirm = document.getElementById('newsletterConfirm');
    const newsletterForm = document.getElementById('newsletterForm');

    subscribeBtn.addEventListener('click', () => {
      const email = emailInput.value.trim();
      if (email && email.includes('@') && email.includes('.')) {
        newsletterConfirm.classList.add('active');
        emailInput.value = '';
      }
    });

    emailInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') subscribeBtn.click();
    });

    // Smooth reveal animations
    const observerOptions = { threshold: 0.1, rootMargin: '0px 0px -50px 0px' };
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.style.opacity = '1';
          entry.target.style.transform = 'translateY(0)';
        }
      });
    }, observerOptions);

    document.querySelectorAll('.product-card, .seasonal-card, .category-card, .highlight-item, .store-result-card').forEach(el => {
      el.style.opacity = '0';
      el.style.transform = 'translateY(20px)';
      el.style.transition = 'opacity 0.5s ease, transform 0.5s ease';
      observer.observe(el);
    });
  </script>
